function Shell({ token, logout, onTokenRefresh }: { token: string; logout: () => void; onTokenRefresh: (t: string) => void }) {
  const [view,setView]=useState<View>("dashboard"); const qc=useQueryClient();
  const query=useQuery({queryKey:["app",token],queryFn:()=>api.getAppData({token}),retry:false});
  const refresh=()=>void qc.invalidateQueries({queryKey:["app",token]});
  if(query.isPending) return <div className="loading"><div className="loader"></div><p>Opening your ledger…</p></div>;
  if(query.error) return <div className="loading"><p>{query.error instanceof Error?query.error.message:"Could not load your account."}</p><button className="primary" onClick={logout}>Return to sign in</button></div>;
  const data=query.data as AppData;
  if(view==="terms") return <Terms back={()=>setView("dashboard")} />;
  return <div className="app-shell"><aside><div className="account"><span>{data.user.email.slice(0,1).toUpperCase()}</span><div><b>{data.user.email}</b><small>Premium trial</small></div></div><nav>{(["dashboard","affiliate","alerts","billing","wallets","transactions","tax"] as View[]).map((v)=><button key={v} className={view===v?"active":""} onClick={()=>setView(v)}><span className="nav-icon">{NAV_ICONS[v]}</span>{v==="tax"?"Tax Center":v[0]?.toUpperCase()+v.slice(1)}</button>)}</nav><div className="aside-bottom"><button onClick={()=>setView("terms")}>Terms</button><button onClick={logout}>Sign out</button></div></aside><main className="workspace">{view==="dashboard"&&<Dashboard data={data} setView={setView}/>} {view==="wallets"&&<Wallets data={data} token={token} refresh={refresh}/>} {view==="transactions"&&<Transactions data={data} token={token} refresh={refresh}/>} {view==="tax"&&<TaxCenter data={data} token={token} refresh={refresh}/>} {view==="alerts"&&<Alerts data={data} token={token} refresh={refresh}/>} {view==="affiliate"&&<Affiliate data={data} token={token} refresh={refresh}/>} {view==="billing"&&<Billing token={token} onTokenRefresh={onTokenRefresh}/>}<footer className="app-footer">© 2026 CryptoBagTracker. All rights reserved. · <a href="mailto:info@cryptobagtracker.io">info@cryptobagtracker.io</a></footer></main><nav className="mobile-nav">{(["dashboard","alerts","billing","wallets","transactions","tax"] as View[]).map((v)=><button key={v} aria-label={v==="tax"?"Tax Center":v} className={view===v?"active":""} onClick={()=>setView(v)}><span className="nav-icon">{v==="transactions"?<PlusIcon size={20}/>:NAV_ICONS[v]}</span><small>{v==="transactions"?"Add":v==="tax"?"Tax":v[0]?.toUpperCase()+v.slice(1)}</small></button>)}</nav></div>;
}

export function App() {
  const [token,setToken]=useState(()=>localStorage.getItem("cbt_session")||""); const [auth,setAuth]=useState<AuthMode|null>(null); const [showTerms,setShowTerms]=useState(false);
  const [showServices,setShowServices]=useState(()=>window.location.pathname.replace(/\/+$/,"")==="/services");
  const referral=useMemo(()=>new URLSearchParams(window.location.search).get("ref")?.trim().toUpperCase()||"",[]);
  useEffect(()=>{if(referral&&!token)setAuth("signup");},[referral,token]);
  useEffect(()=>{const sync=()=>setShowServices(window.location.pathname.replace(/\/+$/,"")==="/services");window.addEventListener("popstate",sync);return ()=>window.removeEventListener("popstate",sync);},[]);
  const goServices=()=>{window.history.pushState(null,"","/services");setShowServices(true);window.scrollTo(0,0);};
  const goHome=()=>{window.history.pushState(null,"","/");setShowServices(false);window.scrollTo(0,0);};
  if(showTerms) return <Terms back={()=>setShowTerms(false)}/>;
  if(showServices) return <Services referral={referral} onAuth={(m)=>{goHome();setAuth(m);}} onHome={goHome} onServices={goServices} onTerms={()=>setShowTerms(true)}/>;
  if(token) return <Shell token={token} logout={()=>{localStorage.removeItem("cbt_session");setToken("");}} onTokenRefresh={(t)=>{localStorage.setItem("cbt_session",t);setToken(t);}}/>;
  if(auth) return <AuthPanel initialMode={auth} referral={referral} onClose={()=>setAuth(null)} onDone={setToken} showTerms={()=>setShowTerms(true)}/>;
  return <Landing referral={referral} onAuth={setAuth} onTerms={()=>setShowTerms(true)} onServices={goServices} onHome={goHome}/>;
}
